const d = $json;
const ok = d.extractedText && d.extractedText.length > 50
  && d.fileName && /\.(pdf|png|jpg|jpeg)$/i.test(d.fileName)
  && (d.fileSizeKB || 0) <= 10240
  && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(d.from || ''));
if (!ok) return { json: { Timestamp: new Date().toISOString(), EventKey: d.EventKey || 'unknown',
  Workflow: 'invoice-extraction', Status: 'rejected_invalid_input',
  FileName: d.fileName || 'missing', Reason: !d.extractedText ? 'no_text' : 'bad_file' } };
return { json: { ...d, input_valid: true } };

const raw = $json.content?.parts?.filter(p => !p.thought).map(p => p.text || '').join('') ?? $json.text ?? '';
const cleaned = raw.replace(/```json/gi,'```').replace(/```/g,'').trim();
let data = null;
const cands = cleaned.match(/\{[\s\S]*\}/g) ?? [];
for (const c of cands.reverse()) {
  try { const p = JSON.parse(c); if (p && p.vendor && p.total !== undefined) { data = p; break; } } catch(e){}
}
const inv = $('Validate Input').item.json;
if (!data) return { json: { ...inv, extraction_ok: false, error: 'Gemini output unparseable' } };
// Basic numeric sanity
const nums = ['subtotal','tax','total'];
for (const k of nums) { if (typeof data[k] === 'string') data[k] = parseFloat(data[k].replace(/[^0-9.-]/g,'')) || 0; }
if (!Array.isArray(data.lineItems)) data.lineItems = [];
const confidence = (data.vendor && data.invoiceNumber && data.total > 0) ? 0.93 : 0.6;
return { json: { ...inv, ...data, extraction_ok: true, ai_confidence: confidence,
  extractedAt: new Date().toISOString() } };

// ── Duplicate & Anomaly Detection ──
// PRODUCTION: query Sheets "Invoice Ledger" for matching invoiceNumber+vendor+total.
// Also compute rolling average per vendor for anomaly detection.
const d = $json;
// Demo: simulate known duplicates and anomaly thresholds
const knownLedger = [
  { invoiceNumber: "CH-2026-4821", vendor: "CloudHost Pro LLC", total: 757.75 },
];
const vendorAvg = { "CloudHost Pro LLC": 740, "Office Supply Depot": 500 };
const isDup = knownLedger.some(k =>
  k.invoiceNumber === d.invoiceNumber && k.vendor === d.vendor && Math.abs(k.total - d.total) < 0.01);
const avg = vendorAvg[d.vendor] || d.total;
const isAnomaly = d.total > avg * 2;
return { json: { ...d, is_duplicate: isDup, is_anomaly: isAnomaly,
  vendorAvgAmount: avg, anomalyRatio: +(d.total / avg).toFixed(2) } };

const d = $json;
return { json: { Timestamp: new Date().toISOString(), EventKey: d.EventKey,
  Workflow: 'invoice-extraction', Status: 'skipped_duplicate',
  Vendor: d.vendor, InvoiceNumber: d.invoiceNumber, Total: d.total,
  SourceEmail: d.from, SourceFile: d.fileName } };

const d = $json;
return { json: { Timestamp: new Date().toISOString(), EventKey: d.EventKey || 'unknown',
  Workflow: 'invoice-extraction', Status: 'extraction_failed',
  SourceEmail: d.from || '', SourceFile: d.fileName || '',
  Error: d.error || 'Unknown extraction failure',
  AiConfidence: d.ai_confidence || 0 } };
